insert into public.teams(id,name,owner_id) values('b1770000-0000-4000-8000-000000000011','Publication fixture','b1770000-0000-4000-8000-000000000001');
insert into public.team_members(team_id,user_id,base_role) values('b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000001','admin');
insert into private.google_drive_credentials(id,connected_by,google_permission_id,google_account_email,vault_secret_id,scope) values('b1770000-0000-4000-8000-000000000021','b1770000-0000-4000-8000-000000000001','publication-test','publication-owner@test.invalid',gen_random_uuid(),'https://www.googleapis.com/auth/drive.file');
insert into public.team_drive_connections(id,team_id,credential_id,root_folder_id,root_folder_name,drive_kind,state,connected_at) values('b1770000-0000-4000-8000-000000000031','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000021','publication-root','Root','my_drive','connected',now());
insert into public.team_materials(id,team_id,connection_id,drive_file_id,name,kind,category,mime_type,drive_version) values
 ('b1770000-0000-4000-8000-000000000041','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000031','publication-video','Video','file','video','video/mp4','1'),
 ('b1770000-0000-4000-8000-000000000042','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000031','publication-catalog','Catalog','file','other','application/vnd.google-apps.spreadsheet','1');
insert into public.team_product_catalogs(material_id,team_id,video_material_id,source_link,product_count,sheet_url,video_link,settings_snapshot) values('b1770000-0000-4000-8000-000000000042','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000041','https://offer.example.invalid/',2,'https://docs.google.com/spreadsheets/d/publication-catalog/edit','https://drive.google.com/file/d/publication-video/view','{}');
create temporary table publication_test as select public.service_save_catalog_publication('b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000001','b1770000-0000-4000-8000-000000000051','b1770000-0000-4000-8000-000000000042',0,'held',null,null,jsonb_build_object('kind','source','materialId','b1770000-0000-4000-8000-000000000041','sourceVersion',private.catalog_publication_source_version('b1770000-0000-4000-8000-000000000041','b1770000-0000-4000-8000-000000000011'))) receipt;
select ok(not has_table_privilege('service_role','private.catalog_video_publication_jobs','select,insert,update,delete'),'job rows have no direct service/browser grants');
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in('private.catalog_video_publication_jobs'::regclass,'private.catalog_publication_targets'::regclass,'private.catalog_publication_baseline_checks'::regclass)),'publication and baseline RLS forced');
select ok(not has_function_privilege('authenticated','public.service_save_catalog_publication(uuid,uuid,uuid,uuid,bigint,text,timestamptz,text,jsonb)','execute'),'browser cannot call trusted policy authority');
select ok(not has_function_privilege('authenticated','public.service_finish_catalog_baseline_check(uuid,uuid,uuid,uuid,text,text,text,uuid,bigint)','execute'),'browser cannot forge provider baseline proof');
select is((select receipt->>'mode' from publication_test),'held','held policy persisted');
select is((select receipt->'active' from publication_test),'null'::jsonb,'metadata is not active delivery proof');
create temporary table publication_baseline as select public.service_begin_catalog_baseline_check('b1770000-0000-4000-8000-000000000061','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000001','b1770000-0000-4000-8000-000000000042',1) context;
select is((select context->>'checkId' from publication_baseline),'b1770000-0000-4000-8000-000000000061','baseline has original check identity');
select is(public.service_catalog_publication_allows_legacy_write('b1770000-0000-4000-8000-000000000042'),false,'legacy writer cannot replace publication-owned video fields');
select is(public.service_finish_catalog_update_write('b1770000-0000-4000-8000-000000000042'),false,'legacy finish cannot erase publication fence');
select is(public.service_resolve_catalog_reconciliation('b1770000-0000-4000-8000-000000000042',(select (context->>'fence')::uuid from publication_baseline),'delivered','legacy'),false,'metadata-only resolver cannot settle video-cell proof');
insert into public.team_catalog_updaters(team_id) values('b1770000-0000-4000-8000-000000000011') on conflict do nothing;
insert into public.team_catalog_updater_items(catalog_material_id,team_id,reconciliation_required) values('b1770000-0000-4000-8000-000000000042','b1770000-0000-4000-8000-000000000011',true) on conflict(catalog_material_id) do update set reconciliation_required=true;
select is((select count(*) from public.service_claim_catalog_reconciliations(3)),0::bigint,'legacy claim excludes publication baseline');
select is((select count(*) from private.catalog_update_reconciliations where catalog_material_id='b1770000-0000-4000-8000-000000000042'),1::bigint,'original baseline marker retained');
create temporary table adopted as select public.service_finish_catalog_baseline_check('b1770000-0000-4000-8000-000000000061','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000001',(select (context->>'fence')::uuid from publication_baseline),'source','2',repeat('a',64)) receipt;
select is((select receipt#>>'{active,target,kind}' from adopted),'source','verified legacy source adopted');
select is((select receipt#>>'{active,target,materialId}' from adopted),'b1770000-0000-4000-8000-000000000041','target derived from stored source binding');
select is((select count(*) from private.catalog_update_reconciliations where catalog_material_id='b1770000-0000-4000-8000-000000000042'),0::bigint,'only original baseline marker released');
select is((select receipt#>>'{job,state}' from adopted),'held','adoption does not itself publish a held job');
select is(public.service_read_catalog_baseline_check('b1770000-0000-4000-8000-000000000061','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000001','b1770000-0000-4000-8000-000000000042'),(select receipt from adopted),'lost finish acknowledgement has exact read-only receipt');
select is(public.service_read_catalog_baseline_check('b1770000-0000-4000-8000-000000000062','b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000001','b1770000-0000-4000-8000-000000000042'),null::jsonb,'missing baseline remains unknown');
select is(public.service_save_catalog_publication('b1770000-0000-4000-8000-000000000011','b1770000-0000-4000-8000-000000000001','b1770000-0000-4000-8000-000000000051','b1770000-0000-4000-8000-000000000042',0,'held',null,null,jsonb_build_object('kind','source','materialId','b1770000-0000-4000-8000-000000000041','sourceVersion',private.catalog_publication_source_version('b1770000-0000-4000-8000-000000000041','b1770000-0000-4000-8000-000000000011'))),(select receipt from publication_test),'configuration replay retains original receipt rather than current state');
select ok(not has_function_privilege('authenticated','public.service_prepare_catalog_publication_cells(uuid,uuid,jsonb)','execute'),'browser cannot inject publication cell recipe');
select ok(has_function_privilege('service_role','public.service_catalog_publication_cells_context(uuid,uuid)','execute'),'trusted worker can read bounded prepared context');
select ok(not has_table_privilege('service_role','private.catalog_publication_cell_writes','select'),'private retained URLs unavailable through raw service table access');
select ok(exists(select 1 from pg_trigger where tgrelid='private.catalog_publication_cell_writes'::regclass and tgname='task_cleanup_reference_fence' and not tgisinternal),'retained recipe participates in cleanup reference fence');
select * from finish();
rollback;
